/**
 * Fix guidance per rule. A value is a string, or an object keyed by the pattern label (the finding title up to the first colon)
 * with '*' as the default. Titles that do not follow `label: file` fall through to '*'.
 */
const REC = {
  "manifest.debuggable": "Set android:debuggable to false for release builds, or remove the attribute so Gradle writes the right value for each build type. Check the merged manifest of the release APK, because a library or a manifest placeholder can add the flag back.",
  "manifest.exported-components": "Set android:exported=\"false\" on every component that only your own app starts. If other apps must reach it, guard it with a signature-level android:permission, check the caller inside the component, and validate every Intent extra and Uri it reads. Apps targeting Android 12 (API 31) must declare android:exported on each component that has an intent filter.",
  "manifest.exported-provider": "Set android:exported=\"false\" on the provider and share individual files through a FileProvider with temporary URI grants. If other apps must query it, declare android:readPermission and android:writePermission with a signature protection level, and use bound arguments in query, update and delete.",
  "manifest.weak-permission": "Declare the custom permission in your manifest with android:protectionLevel=\"signature\", so only apps signed with your certificate can hold it. Permissions at the normal or dangerous level can be requested by any app and do not restrict who calls the component.",
  "manifest.backup": "Set android:allowBackup=\"false\" if the app holds nothing worth restoring. Otherwise keep backups on and exclude databases, shared preferences and tokens with android:dataExtractionRules (Android 12 and later) and android:fullBackupContent (Android 11 and earlier), using <exclude> entries.",
  "manifest.task-affinity": "Set android:taskAffinity=\"\" on activities that must stay in the app's own task, and use launchMode standard or singleTop in place of singleTask or singleInstance where the design allows it. Remove android:allowTaskReparenting from activities that show sign-in or payment screens.",
  "manifest.sdk-levels": "Raise targetSdkVersion to the level Google Play currently requires for app updates and test the app on it. The target level switches on platform protections for your app: runtime permissions from API 23, distrust of user-installed CAs from API 24, scoped storage from API 29 and mandatory android:exported from API 31. Raise minSdkVersion as far as your users allow, since old releases no longer get security patches.",
  "manifest.grant-uri": "Set android:grantUriPermissions=\"false\" unless the provider hands out URIs. When it does, list only the paths to share with <grant-uri-permission android:pathPrefix=\"...\"> in place of the global attribute, and grant access per Intent with FLAG_GRANT_READ_URI_PERMISSION.",
  "manifest.safe-browsing-off": "Remove the android.webkit.WebView.EnableSafeBrowsing meta-data entry that sets it to false, so the default (enabled) applies. Handle WebViewClient.onSafeBrowsingHit if you want to show your own warning page when a site is flagged.",
  "manifest.deeplinks": "Use Android App Links: an https scheme, an exact android:host, android:autoVerify=\"true\" on the intent filter, and a Digital Asset Links file at /.well-known/assetlinks.json on that host. Remove plain http schemes and wildcard hosts, and validate every parameter taken from the link before the app acts on it.",
  "manifest.risky-attributes": {
    "*": "Remove the manifest setting that opens this exposure from release builds. Check the merged manifest of the shipped APK to confirm it is gone.",
    "Test-only build": "Remove android:testOnly=\"true\" from the manifest of every build you distribute. Check the merged manifest of the release variant, since a build script or manifest placeholder may set it, and build the shipping APK with the release task.",
    "Shared user ID": "Remove android:sharedUserId, which is deprecated since API 29, and share data through a FileProvider, a ContentProvider or a bound Service protected by a signature permission. For an installed base that already uses it, migrate the shared files first, then set android:sharedUserMaxSdkVersion=\"32\" so new installs on Android 13 and later get their own user ID.",
    "Legacy external storage": "Remove android:requestLegacyExternalStorage and android:preserveLegacyExternalStorage, and move to scoped storage. Write app files to Context.getExternalFilesDir() or internal storage, use MediaStore for shared media, and use the Storage Access Framework (ACTION_OPEN_DOCUMENT) for files the user picks. The request flag has no effect once you target Android 11 (API 30).",
    "Task reparenting allowed": "Remove android:allowTaskReparenting or set it to false. Combine it with android:taskAffinity=\"\" on activities that show sign-in or payment screens, so another app's task cannot take them over.",
    "Dialer secret code": "Move the receiver with the android_secret_code filter into src/debug/AndroidManifest.xml so release builds do not contain it. If the hidden menu has to ship, require a signed-in administrator before it shows or changes anything."
  },
  "network.cleartext": "Set android:usesCleartextTraffic=\"false\", and in the network security config set cleartextTrafficPermitted=\"false\" in base-config. Delete the domain-config entries that allow http and move those endpoints to HTTPS. Apps targeting Android 9 (API 28) and later already block cleartext by default.",
  "network.user-ca": "Remove <certificates src=\"user\" /> from base-config and domain-config so only <certificates src=\"system\" /> is trusted. If debug builds need a proxy CA, put the user anchor inside <debug-overrides>, which applies only to debuggable builds. Never set overridePins=\"true\" in a release build, and target API 24 or higher, where user CAs are not trusted by default.",
  "network.expired-pins": "Ship an updated <pin-set expiration=\"...\"> with new pins before the date passes. After the expiration date Android stops enforcing the pins and falls back to normal certificate validation, so pinning gives no protection. Include a backup pin for a spare key, so a certificate rotation does not lock users out.",
  "network.cordova-allowlist": "Replace wildcard origins in config.xml, such as <access origin=\"*\" /> and <allow-navigation href=\"*\" />, with the exact HTTPS hosts the app calls. Add a Content-Security-Policy meta tag to the app's pages and limit <allow-intent> entries to the schemes you use.",
  "network.no-pinning": "Pin the certificate or public key of your API hosts in the network security config with <pin-set expiration=\"...\"> and at least one backup pin, or in OkHttp with CertificatePinner.Builder().add(\"api.example.com\", \"sha256/...\"). Pin an intermediate CA when you rotate leaf certificates often, and test the rotation path before release so an updated certificate does not break the app.",
  "signature.verdict": {
    "*": "Sign release builds with your own release key through a Gradle signingConfig or Play App Signing, and verify the result with apksigner verify --verbose. Sign every APK part with the same certificate.",
    "APK signature does not verify": "Rebuild and re-sign the APK, then run apksigner verify --verbose on the output. A signature that fails verification means the file changed after signing, so check your build pipeline for steps that modify the APK after zipalign and signing.",
    "Signed with a debug certificate": "Sign release builds with your own release key through a Gradle signingConfig or enroll in Play App Signing. Keep the release keystore out of the repository, and never publish a build signed with the Android debug keystore.",
    "Only a v1 signature, with minSdk 26 or lower": "Enable APK Signature Scheme v2 and v3 in addition to v1. Gradle does this by default when you build with the Android Gradle plugin and a current build-tools version, so check that enableV2Signing and enableV3Signing are not set to false. The v1 scheme leaves parts of the APK unprotected, which is how Janus-style attacks work on older devices.",
    "Split APK signature does not verify": "Rebuild the bundle and sign all splits in one pipeline, then verify each part with apksigner verify. Do not edit or repackage a split after signing.",
    "Split APK signed by a different certificate": "Sign the base APK and every split with the same release certificate. Android refuses to install splits signed by different keys, so a mismatch usually means a split came from another build or another signing configuration."
  },
  "code.trust-all-tls": {
    "*": "Remove the custom trust or hostname code and use the platform defaults, which validate the certificate chain and the host name. If you must trust a private CA, declare it in the network security config with <trust-anchors>.",
    "Empty checkServerTrusted": "Delete the custom X509TrustManager and use the platform default, which checks the chain against the system trust store. To trust a private CA, declare it in the network security config under <trust-anchors>, or build a TrustManager from a KeyStore holding that CA through TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm()).",
    "HostnameVerifier that always returns true": "Delete the custom HostnameVerifier and use HttpsURLConnection.getDefaultHostnameVerifier(), or the default in OkHttp. The default compares the host in the URL with the names in the certificate, which an always-true verifier skips.",
    "WebView proceeds after an SSL error": "Call handler.cancel() in onReceivedSslError and show an error page. Calling proceed() lets the page load with an invalid certificate, and Google Play rejects apps that do it.",
    "Allow-all hostname verifier": "Replace ALLOW_ALL_HOSTNAME_VERIFIER or AllowAllHostnameVerifier with the platform default hostname verifier. Move the code to HttpsURLConnection or OkHttp, since the Apache HTTP client was deprecated in API 22 and removed from the SDK in API 23."
  },
  "code.webview-debugging": "Call WebView.setWebContentsDebuggingEnabled(true) only inside a debug check such as if (BuildConfig.DEBUG). Leave it off in release builds, because anyone with adb can then attach Chrome DevTools to the app's WebViews and read or script their pages.",
  "secrets.private-material": "Remove the private key or credential from the APK and treat it as exposed: revoke it and issue a new one. Keep provider secrets on your server and let the app call your backend, or hand the app a short-lived token after sign-in. For keys the app needs on the device, generate them in the Android Keystore at runtime.",
  "native.hardening": "Rebuild the library with the NDK hardening flags: -fstack-protector-strong, -D_FORTIFY_SOURCE=2 with -O2, position-independent code, and the linker flags -Wl,-z,relro, -Wl,-z,now and -Wl,-z,noexecstack. Drop any -rpath linker flag and strip symbols from the release build with -s or the Gradle strip step. For a prebuilt third-party library, update to a release that is built with these flags or ask the vendor for one.",
  "package.leftover-files": {
    "*": "Exclude the file from the packaged APK and check the output with unzip -l. If it held a secret, rotate that secret.",
    "Keystore or private key file": "Remove the keystore or private key from assets, res/raw and the app module, and treat it as exposed. Keep signing keys outside the repository and the APK, and for a client certificate fetch it from your server after sign-in or generate the key pair in the Android Keystore on the device.",
    "Obfuscation mapping file": "Exclude mapping.txt and similar files from the APK. R8 writes the mapping to build/outputs/mapping/ for you to upload to Play Console or your crash reporter, which use it to read obfuscated stack traces.",
    "JavaScript source map": "Stop the bundler from writing the .js.map file into the app's assets. For React Native, point --sourcemap-output at a path outside the app, and upload the map to your crash reporter so stack traces stay readable."
  },
  "code.hardcoded-credential": {
    "*": "Remove the fixed credential from the code and rotate it. Authenticate against your server, which checks a salted password hash and returns a session token.",
    "Credential compared with a hardcoded value": "Delete the hardcoded comparison, and any backdoor user name or password with it, and rotate the credential. Authenticate against your server, which verifies a salted hash and returns a short-lived session token.",
    "Keystore opened with a literal password": "Remove the literal password from the code. Use KeyStore.getInstance(\"AndroidKeyStore\"), which needs no password and keeps the key material out of the app's process. If you must open a PKCS12 or BKS file, derive the password at runtime from a user secret or an Android Keystore key.",
    "Database opened with a literal key": "Generate a random passphrase on first run and wrap it with an AES/GCM/NoPadding key in the Android Keystore. Store only the wrapped value, and pass the unwrapped passphrase to SQLCipher (SupportFactory) when you open the database.",
    "Hardcoded value compared with a credential": "Delete the hardcoded comparison, and any backdoor user name or password with it, and rotate the credential. Authenticate against your server, which verifies a salted hash and returns a short-lived session token."
  },
  "code.weak-crypto": {
    "*": "Use authenticated encryption with Cipher.getInstance(\"AES/GCM/NoPadding\"), a fresh random IV per message, and a key generated in the Android Keystore. Take random values from SecureRandom.",
    "Weak cipher or ECB mode": "Use Cipher.getInstance(\"AES/GCM/NoPadding\") with a 12-byte random IV per message and a 128-bit tag through GCMParameterSpec. ECB mode shows repeated plaintext blocks, DES, RC2 and RC4 are broken, and Cipher.getInstance(\"AES\") alone selects ECB on Android.",
    "Constant IV": "Generate a new IV for every encryption with SecureRandom, 12 bytes for GCM and 16 for CBC, and store it in front of the ciphertext. When you encrypt with an Android Keystore key, let the Cipher create the IV and read it with cipher.getIV(). Reusing an IV with GCM breaks both confidentiality and authenticity.",
    "Key built from a string literal": "Replace SecretKeySpec built from a literal with a key from KeyGenerator.getInstance(\"AES\", \"AndroidKeyStore\"), which keeps the key material outside your process. Rotate the literal that shipped, since anyone with the APK has it.",
    "RSA without OAEP padding": "Use Cipher.getInstance(\"RSA/ECB/OAEPWithSHA-256AndMGF1Padding\") for RSA encryption, and RSASSA-PSS or SHA256withRSA for signatures. In practice encrypt a random AES key with RSA-OAEP and the data with AES/GCM/NoPadding. PKCS1 padding is open to padding-oracle attacks.",
    "Weak key size": "Generate RSA keys of 2048 bits or more, 3072 for long-lived data, AES keys of 128 or 256 bits, and EC keys on secp256r1. For Keystore keys set the size with KeyGenParameterSpec.Builder.setKeySize().",
    "SecureRandom with a fixed seed": "Create SecureRandom with no seed argument and never call setSeed, so the system supplies the entropy. A fixed seed can make the output repeatable, and anyone who knows it can compute every key, IV or token the generator produces.",
    "Low PBKDF2 iteration count": "Use PBKDF2WithHmacSHA256 (API 26 and higher) with at least 600000 iterations, which is the OWASP guidance for HMAC-SHA-256, a random 16-byte salt from SecureRandom and a 256-bit output. Run it off the main thread and raise the count as devices get faster.",
    "Home-made XOR encryption": "Replace the XOR routine with AES/GCM/NoPadding through javax.crypto.Cipher, or with the Aead primitive from Tink. XOR with a repeating key falls to frequency analysis, and the key sits in the app next to the code.",
    "Bouncy Castle provider requested by name": "Drop the \"BC\" provider argument and call Cipher.getInstance with the algorithm name, so the platform's Conscrypt provider serves it. Android 9 stopped serving some algorithms from the bundled BC provider. If you need Bouncy Castle itself, bundle the library and register it with Security.addProvider.",
    "MD5 or SHA-1 digest": "Use MessageDigest.getInstance(\"SHA-256\") or SHA-512 for integrity checks, and HmacSHA256 with a secret for message authentication. For passwords use PBKDF2, scrypt or Argon2 with a random salt, since a plain digest is fast to brute-force.",
    "Fixed initialization vector": "Generate a new random IV for every encryption with SecureRandom, 12 bytes for AES/GCM/NoPadding, and store it next to the ciphertext. Let Cipher.init create the IV and read it from cipher.getIV(). Never reuse an IV with the same key."
  },
  "code.webview-js-local": {
    "*": "Enable JavaScript only for pages from your own HTTPS origin. Serve local files through WebViewAssetLoader from androidx.webkit.",
    "WebView loads a local file with JavaScript on": "Serve local content through WebViewAssetLoader from androidx.webkit, which exposes it at https://appassets.androidplatform.net/ in place of file:// URLs, and call setAllowFileAccess(false). Never load files from external storage into a WebView that has JavaScript enabled, because any app that can write the file controls the script.",
    "WebView with JavaScript on": "Call setJavaScriptEnabled(true) only for pages you control. Add a WebViewClient whose shouldOverrideUrlLoading checks each URL against an allowlist of exact HTTPS hosts, and do not pass untrusted URLs to loadUrl."
  },
  "code.cleartext-url": "Change http:// and ftp:// URLs to https:// and set cleartextTrafficPermitted=\"false\" in the network security config, so a missed URL fails instead of leaking. Confirm that the server speaks TLS 1.2 or later with a valid certificate, and replace FTP with SFTP or an HTTPS API.",
  "code.sensitive-logging": "Delete the log calls that print passwords, tokens or credentials. Wrap debug logging in if (BuildConfig.DEBUG), or plant a Timber tree only in debug builds, and add an R8 rule such as -assumenosideeffects class android.util.Log { public static int d(...); public static int v(...); } to strip the calls from release builds.",
  "code.external-storage": "Write private data with Context.getFilesDir() or Context.getExternalFilesDir(), and use MediaStore or the Storage Access Framework (ACTION_CREATE_DOCUMENT) for files the user should keep. Encrypt sensitive content before it leaves internal storage, since any app with storage access may read shared locations.",
  "code.client-root-check": "Request an integrity verdict from the Play Integrity API and verify it on your server, which then decides whether to serve sensitive data or actions. Treat the local root check as a hint that slows an attacker, because hooking frameworks can patch it out.",
  "code.sms-send": "Send SMS only after a user action in the foreground, and never build the number or text from an Intent extra without validating it. Where possible start an ACTION_SENDTO Intent with an sms: URI, which opens the messaging app and needs no SEND_SMS permission.",
  "code.no-tamper-check": "Read the signing certificate with PackageManager.getPackageInfo(packageName, GET_SIGNING_CERTIFICATES), compare its SHA-256 digest to the value you expect, and request a verdict from the Play Integrity API. Check that verdict on your server, since a client-side comparison can be patched out of a repackaged APK.",
  "code.world-readable-file": {
    "*": "Create files with MODE_PRIVATE only (the 0 mode), and share content through a FileProvider with temporary URI grants. Remove setReadable(true, false) and setWritable(true, false) calls, and check older devices for files that earlier app versions left behind.",
    "World-readable mode as a number": "Open files and preferences with mode 0 (MODE_PRIVATE). Modes 1, 2, 3, 5, 6 and 7 are the world-readable and world-writable modes, which Android blocks from API 24. Share files through a FileProvider instead.",
    "File opened to every app": "Use setReadable(true, true) or no call at all, so only the owner can read the file. Share files through a FileProvider with temporary grants, and keep the file in the app's private directory."
  },
  "code.webview-settings": {
    "*": "Turn off the WebView feature unless the page needs it. Limit navigation to an allowlist of HTTPS hosts you control.",
    "Java object exposed to web content": "Expose only the methods the page needs, mark each with @JavascriptInterface, and load the interface only into pages from your own HTTPS origin. WebViewCompat.addWebMessageListener lets you list the allowed origins, which addJavascriptInterface cannot do.",
    "WebView can read files through file URLs": "Call setAllowFileAccessFromFileURLs(false) and setAllowUniversalAccessFromFileURLs(false), which are the defaults on current Android. Load packaged pages through WebViewAssetLoader so they get an https origin instead of a file origin.",
    "WebView file access enabled": "Call setAllowFileAccess(false), which is the default when you target Android 11 (API 30) or later. Load packaged pages through WebViewAssetLoader and its AssetsPathHandler.",
    "Mixed content in compatibility mode": "Set setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW), the default for apps targeting API 21 and later. Move every subresource to HTTPS so nothing needs the fallback.",
    "WebView can read content providers": "Call setAllowContentAccess(false) unless the WebView must load content:// URLs. If it must, restrict those URLs to your own providers and check each URL before loading it.",
    "Page loaded with a file:// base URL": "Pass an https:// base URL that you control to loadDataWithBaseURL, or serve the content through WebViewAssetLoader. A file:// base gives the page the file origin and with it a route to local files.",
    "JavaScript built from data and run in a WebView": "Stop concatenating data into loadUrl(\"javascript:...\") and evaluateJavascript calls. Encode values with JSONObject.quote(), or pass them through WebMessagePort or WebViewCompat.addWebMessageListener so the page receives them as data and not as code.",
    "Intercepted request answered from a local file": "In shouldInterceptRequest, answer only from an allowlist of paths and reject the rest after resolving the name with getCanonicalPath(). Better, switch to WebViewAssetLoader with its PathHandler classes, which serve only the directory you register.",
    "Mixed content always allowed": "Set the mode to MIXED_CONTENT_NEVER_ALLOW and move every subresource to HTTPS. If an old page forces a fallback, use MIXED_CONTENT_COMPATIBILITY_MODE, which follows Chrome's blocking rules."
  },
  "code.insecure-random": "Create one java.security.SecureRandom, call nextBytes to fill a buffer, and encode it with Base64 or hex for tokens, IVs, nonces and salts. For a numeric one-time code use secureRandom.nextInt(1000000) and format it to six digits. Do not seed it.",
  "code.plaintext-token-prefs": "Encrypt the value with an AES/GCM/NoPadding key held in the Android Keystore before saving it, for example through Tink's Aead with AndroidKeysetManager. EncryptedSharedPreferences from androidx.security:security-crypto does the same, but that library is deprecated, so prefer Tink for new code. Keep tokens short-lived and exclude the file from backups.",
  "code.dynamic-execution": {
    "OS command built from a string": "Avoid shell commands. If one is needed, pass an argument array to ProcessBuilder with a fixed program name and check every argument against an allow-list.",
    "Over-the-air code update library": "Sign every update bundle, verify the signature before it loads, serve updates over pinned TLS and limit the channel to your own server.",
    "*": "Load code only from your own APK or a Play Feature Delivery module. Avoid running commands built from outside data.",
    "Dynamic code loading": "Ship the code in your APK or a Play Feature Delivery module in place of DexClassLoader or PathClassLoader on downloaded files. If dynamic loading is unavoidable, verify a signature on the file before loading, keep it in app-private storage, and set it read-only, which Android 14 requires for dynamically loaded files.",
    "Code loaded from another app": "Remove createPackageContext with CONTEXT_INCLUDE_CODE or CONTEXT_IGNORE_SECURITY, because loading another app's classes runs its code with your permissions. Talk to the other app through a bound Service or a ContentProvider guarded by a signature permission.",
    "Native library loaded from a built path": "Load libraries by name with System.loadLibrary(\"name\"), which resolves only inside the app's native library directory. If System.load is required, use a constant path under your own directory and check the file's SHA-256 digest first.",
    "OS command execution": "Replace Runtime.exec and ProcessBuilder with an Android API for the task. If a command is unavoidable, use a fixed executable path, pass arguments as a String array and never as one concatenated string, and check every outside value against an allowlist."
  },
  "code.intent-safety": {
    "Service returns a binder without a caller check": "Check the caller inside the binder with enforceCallingPermission or getCallingUid, or keep the service unexported or behind a signature permission.",
    "Token returned in an activity result": "Return only what the caller needs, check getCallingPackage() against the app that may receive it, or guard the activity with a signature permission.",
    "*": "Use explicit Intents with setPackage or setComponent. Validate any Intent or extra that comes from another app before acting on it.",
    "PendingIntent without a mutability flag": "Pass PendingIntent.FLAG_IMMUTABLE on every PendingIntent, and FLAG_MUTABLE only where the receiver must fill in fields, such as inline reply. Apps targeting Android 12 (API 31) throw an exception when neither flag is set. Wrap an explicit Intent with setComponent or setPackage.",
    "Broadcast sent without a receiver permission": "Send the broadcast with a receiverPermission argument, sendBroadcast(intent, \"com.example.permission.X\"), where the permission has a signature protection level, or make it explicit with Intent.setPackage(getPackageName()). For events inside your own process use a Kotlin SharedFlow or similar in place of a broadcast.",
    "Intent built from a URL": "Do not start the Intent that Intent.parseUri or Intent.getIntent returns. Parse the URL with Uri.parse, check the scheme and host against an allowlist, and build your own explicit Intent. If you must keep the parsed Intent, call addCategory(CATEGORY_BROWSABLE), setComponent(null) and setSelector(null) on it first.",
    "Sensitive data in an implicit Intent": "Send an explicit Intent with setPackage or setComponent so only the intended app receives it. Keep tokens, one-time codes and card data out of Intent extras, and pass a reference that the receiver exchanges for the data through an authenticated bound Service.",
    "Receiver registered for any app": "Register the receiver with the RECEIVER_NOT_EXPORTED flag through ContextCompat.registerReceiver, or pass a broadcastPermission with a signature protection level. Apps targeting Android 14 must pass one of the export flags for receivers registered at runtime.",
    "Mutable PendingIntent": "Use FLAG_IMMUTABLE, and build the PendingIntent around an explicit Intent with setComponent. FLAG_MUTABLE lets the receiving app change the Intent through fillIn, so keep it for features that need it, such as inline reply and bubbles.",
    "Unsafe implicit PendingIntent override": "Remove FLAG_ALLOW_UNSAFE_IMPLICIT_INTENT and wrap an explicit Intent in the PendingIntent. Android 14 blocks a mutable PendingIntent whose base Intent has no component or package, and this flag turns that check off.",
    "Sticky broadcast": "Replace sendStickyBroadcast, which is deprecated since API 21, with a regular explicit broadcast or a state store such as DataStore. Any app can read a sticky broadcast and you cannot limit it to receivers that hold a permission.",
    "Launch protection removed": "Remove the removeLaunchSecurityProtection() call, which turns off the platform's checks on nested Intents. If you forward an Intent from an extra, validate its component, flags and data against what you expect before you start it.",
    "Nested Intent forwarded": "Do not call startActivity on an Intent read from an extra. Copy only the fields you need into a new explicit Intent, or check that the target component belongs to your own package and is not exported to others. Android 13 and later add launch checks for nested Intents, which an explicit copy keeps working."
  },
  "code.sql-concatenation": "Bind the values: db.rawQuery(\"SELECT * FROM t WHERE id = ?\", new String[]{id}), SQLiteDatabase.query, update and delete with whereArgs, or a Room @Query with :param. For table or column names that vary, compare the name with a fixed allowlist, because those parts cannot be bound.",
  "code.zip-slip": "Build the destination File for each entry, call getCanonicalPath(), and reject the entry unless that path starts with the canonical target directory followed by File.separator. Skip entries with absolute paths, and cap the total uncompressed size to stop zip bombs.",
  "code.legacy-tls": {
    "*": "Use the platform's default TLS configuration. It negotiates TLS 1.2 or 1.3 with modern cipher suites and checks certificates.",
    "Weak TLS cipher suites enabled": "Remove the setEnabledCipherSuites call and let the platform choose, which excludes NULL, EXPORT, RC4 and DES suites. If you must restrict the list, use only TLS 1.2 and 1.3 AEAD suites, or OkHttp's ConnectionSpec.RESTRICTED_TLS.",
    "TLS checks turned off by an insecure socket factory": "Replace SSLCertificateSocketFactory.getInsecure with HttpsURLConnection.getDefaultSSLSocketFactory() or the OkHttp default. To trust a private CA, declare it in the network security config under <trust-anchors>.",
    "Deprecated Apache HTTP client": "Replace DefaultHttpClient with HttpsURLConnection or OkHttp. The Apache client was deprecated in API 22 and removed from the SDK in API 23, so it is not updated for current TLS.",
    "Legacy protocol": "Request SSLContext.getInstance(\"TLS\") for the platform default, or \"TLSv1.2\" as the lowest version. Remove SSLv3, TLSv1 and TLSv1.1 from setEnabledProtocols, since servers and current Android releases reject them."
  },
  "code.fileprovider-root": "Narrow each entry in the res/xml file provider paths file to the folder that holds shared files, for example <files-path name=\"shared\" path=\"shared/\" />. Remove <root-path>, and avoid path=\"\" or path=\".\" because they cover the whole directory tree.",
  "code.clipboard-write": "Do not copy passwords or tokens to the clipboard. If the user asks to copy a value, mark the ClipData with ClipDescription.EXTRA_IS_SENSITIVE (Android 13 and later) so keyboards and the preview hide it, and clear it with ClipboardManager.clearPrimaryClip() after a short delay.",
  "code.no-flag-secure": "Call window.setFlags(FLAG_SECURE, FLAG_SECURE) before setContentView in activities that show balances, tokens or personal data. FLAG_SECURE also blanks the recent-apps thumbnail, and on Android 13 and later Activity.setRecentsScreenshotEnabled(false) hides only that thumbnail.",
  "code.unused-permissions": "Delete the uses-permission entry from AndroidManifest.xml if no code needs it. If a library adds it to the merged manifest, remove it with tools:node=\"remove\" on the entry. Ask for dangerous permissions at runtime, at the moment the feature that needs them runs.",
  "code.keyboard-cache": {
    "*": "Set android:inputType to textPassword or numberPassword for secrets, and to textNoSuggestions for other sensitive text, so the keyboard does not learn the input. Add android:importantForAutofill=\"no\" to the field if autofill should not offer to save it.",
    "Sensitive field lets the keyboard learn": "Add android:imeOptions=\"flagNoPersonalizedLearning\" to the field, or set EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING in code. Combine it with a textNoSuggestions or password input type, and use autofill hints so a password manager fills the field instead of the keyboard."
  },
  "code.path-traversal": {
    "Remote file name used as a path": "Reduce the name to its last path segment with new File(name).getName(), build the target with new File(dir, safeName), and check that getCanonicalPath() starts with the directory's canonical path before writing.",
    "*": "Resolve the File and compare getCanonicalPath() with the canonical path of the directory it must stay in. Reject any path that leaves it.",
    "Display name from a provider used as a file name": "Keep only the last path element with new File(name).getName(), reject names that contain \"..\", or generate your own file name with UUID.randomUUID(). Then resolve the File inside the target directory and check that getCanonicalPath() starts with that directory's canonical path.",
    "File built from a Uri path segment": "Resolve the File, compare its getCanonicalPath() with the canonical path of the allowed directory, and throw if it does not start with it. In a ContentProvider.openFile, apply the same check to every Uri before you open the file, so a segment such as ../../x cannot leave the shared folder."
  },
  "code.unsafe-deserialization": {
    "*": "Do not rebuild objects from data another app can supply. Parse JSON into concrete types and validate the fields afterwards.",
    "readObject that deletes or opens files": "Remove file, command and delete operations from readObject, which runs on every deserialized instance. Use Parcelable or JSON and validate the fields after parsing. If Java serialization stays, subclass ObjectInputStream and override resolveClass to allow only the classes you expect.",
    "Jackson polymorphic typing turned on": "Remove enableDefaultTyping and activateDefaultTyping. Use @JsonTypeInfo on specific fields with a PolymorphicTypeValidator that allows only your own base types, or bind to a concrete class.",
    "Object read from a stream": "Do not call ObjectInputStream.readObject on data from the network, from files other apps can write or from Intent extras. Switch to JSON with kotlinx.serialization or Moshi into a concrete data class, or add a resolveClass allowlist.",
    "Class chosen from parcel or stream data": "Do not pass a string from a Parcel or stream to Class.forName. Map an allowed identifier to a known class with a fixed when or switch statement. For Parcelables use Parcel.readParcelable(ClassLoader, Class) on API 33 and later so the type is fixed by the caller."
  },
  "code.weak-host-check": "Parse the URL with Uri.parse or OkHttp's HttpUrl, then compare getHost() with an allowlist using equals. To allow subdomains, test host.equals(domain) || host.endsWith(\".\" + domain), and require the https scheme. A bare endsWith(\"example.com\") also accepts evil-example.com.",
  "code.link-parameter-to-url": {
    "*": "Treat the parameter or extra as untrusted. Parse it with Uri.parse and accept only the https scheme and hosts from an exact allowlist before the app loads or contacts the URL.",
    "Text field loaded as a URL": "Parse the field value with Uri.parse before loadUrl, require the https scheme and a host from an allowlist, and reject javascript: and file: schemes. To open a URL the user typed, start an ACTION_VIEW Intent so the browser handles it.",
    "Link parameter reaches a URL sink": "Validate the scheme and host of getQueryParameter and getStringExtra values against exact allowed hosts before they reach Uri.parse, loadUrl, setData or an HTTP client. Where you can, pass an identifier and let the app or server look up the URL."
  },
  "code.untrusted-result-uri": "Check the Uri from onActivityResult before opening it: accept only the content:// scheme, reject file:// Uris and the authority of your own provider, and read it with ContentResolver.openInputStream. Copy the data to a file whose name you choose, and prefer ActivityResultContracts.OpenDocument, which returns a Uri with a narrow grant.",
  "code.secret-in-url": "Send tokens and passwords in the Authorization header or in an HTTPS POST body. With OkHttp, add an Interceptor that sets the Authorization header on each request, and rotate any token that was already sent in a URL, since servers, proxies and logs may have stored it.",
  "code.serializable-native-pointer": "Mark the pointer field transient, or stop implementing Serializable on the class. Rebuild the native handle after deserialization from a safe value, and make the native free method check that the pointer is nonzero and owned by this object.",
  "code.encoded-constant": "Remove the secret from the code and fetch it from your server after the user signs in, or generate it at runtime in the Android Keystore. Anything shipped in the APK is readable, so rotate the value that was encoded.",
  "code.xxe": {
    "*": "Disable DTDs and external entities on every XML parser that reads data from outside the app. Configure the parser to reject a DOCTYPE outright before the first parse.",
    "XML parser without entity protection": "On DocumentBuilderFactory and SAXParserFactory call setFeature(\"http://apache.org/xml/features/disallow-doctype-decl\", true) and setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true). On XMLInputFactory set SUPPORT_DTD and IS_SUPPORTING_EXTERNAL_ENTITIES to false, and set the parser up before the first parse.",
    "XMLDecoder on input": "Stop using java.beans.XMLDecoder on outside data, since it can call arbitrary methods. Parse the XML with a DocumentBuilder that has DTDs disabled, or switch the format to JSON."
  },
  "code.fragment-injection": "Make isValidFragment return true only for the fragment class names you list, for example return MyFragment.class.getName().equals(fragmentName). Set the activity to android:exported=\"false\" if no other app opens it, and target API 19 or higher, where the platform enforces this check.",
  "code.biometric-keystore": {
    "*": "Tie the biometric check to a Keystore key that needs user authentication. Pass a BiometricPrompt.CryptoObject so a successful check is required for the key operation.",
    "Biometric prompt without a CryptoObject": "Call BiometricPrompt.authenticate(promptInfo, new BiometricPrompt.CryptoObject(cipher)) with a Cipher initialized from an Android Keystore key created with setUserAuthenticationRequired(true). Decrypt with the cipher from the AuthenticationResult, since a prompt without a CryptoObject can be bypassed by hooking its callback. FingerprintManager is deprecated, so move to BiometricPrompt.",
    "Device credential accepted as a biometric": "Allow the device PIN or pattern only if it matches your threat model. For key-bound authentication use setAllowedAuthenticators(BIOMETRIC_STRONG), because DEVICE_CREDENTIAL combined with a CryptoObject is not supported on Android 10 and lower.",
    "Key survives new biometric enrollment": "Call setInvalidatedByBiometricEnrollment(true), which is the default, so adding a fingerprint or face invalidates the key. Catch KeyPermanentlyInvalidatedException when you initialize the cipher, send the user back through sign-in and create a new key.",
    "Key usable without user authentication": "Call setUserAuthenticationRequired(true) in KeyGenParameterSpec.Builder for keys that protect secrets. On API 30 and later add setUserAuthenticationParameters(0, AUTH_BIOMETRIC_STRONG) to require authentication for every use of the key.",
    "Key stays unlocked for a time window after authentication": "Create the key with setUserAuthenticationParameters(0, AUTH_BIOMETRIC_STRONG) so every use needs a fresh biometric check, and pass a CryptoObject to BiometricPrompt. If a time window is a real requirement, keep it to a few seconds and gate only low-value operations.",
    "Key usable on a locked device": "Call setUnlockedDeviceRequired(true) on keys that protect user data, so the key cannot be used while the screen is locked. Keep the false setting only for keys a background service must use, and document why.",
    "Keystore key without StrongBox": "Call setIsStrongBoxBacked(true) when generating keys and catch StrongBoxUnavailableException to fall back to the default hardware-backed Keystore. Check PackageManager.FEATURE_STRONGBOX_KEYSTORE first, and key attestation can confirm where a key lives.",
    "Deprecated fingerprint API": "Replace FingerprintManager with androidx.biometric BiometricPrompt, and set the allowed authenticators to BIOMETRIC_STRONG. Pass a CryptoObject so the key operation, not just a callback, proves the user was present."
  },
  "code.sensitive-notification": "Keep the secret out of the notification text. Set setVisibility(NotificationCompat.VISIBILITY_PRIVATE) and supply a setPublicVersion() notification that omits the value, so the lock screen shows no content. Show one-time codes inside the app.",
  "code.device-identifiers": "Remove the IMEI, serial, MAC and SIM identifiers. Use a random UUID stored in app-private storage for per-install identity, or the advertising ID with user consent, which needs the com.google.android.gms.permission.AD_ID permission on Android 13 and later. Apps cannot read the IMEI or serial on Android 10 and later without a privileged permission.",
  "code.insecure-bluetooth": {
    "*": "Use secure RFCOMM sockets, which require pairing. Authenticate peers again at the application layer.",
    "Insecure RFCOMM socket": "Use createRfcommSocketToServiceRecord and listenUsingRfcommWithServiceRecord, which require an encrypted and authenticated link with a paired device. Authenticate the peer again at the application layer before you accept commands.",
    "Discoverable without a time limit": "Set EXTRA_DISCOVERABLE_DURATION to the shortest time you need. The default is 120 seconds, and a value of 0 keeps the device discoverable without a limit."
  },
  "code.local-server": "Bind the server to the loopback address with InetAddress.getByName(\"127.0.0.1\"), and require an authentication token on each request, since any app on the phone can connect to a loopback port. For LocalServerSocket, compare the caller's uid from getPeerCredentials() with the uid you expect, and stop the server when the feature is idle.",
  "code.debug-leftovers": {
    "Debug or admin endpoint": "Block /actuator, /swagger, /graphiql and similar paths on production servers and remove the URLs from the app.",
    "*": "Keep development settings in the debug source set or a debug build type. Release builds then cannot contain them.",
    "Private IP address": "Remove the hardcoded private address and define endpoints per build type with buildConfigField. Release builds then point at production only.",
    "Staging or development host": "Move staging and development hosts into src/debug or a separate product flavor, and read the release endpoint from a buildConfigField. Release builds then contain no test backends.",
    "StrictMode left on": "Call StrictMode.setThreadPolicy and setVmPolicy only inside if (BuildConfig.DEBUG). Drop penaltyDeath and penaltyDialog from release code, since they crash the app or show dialogs to users.",
    "Debug build flag set": "Replace the constant with BuildConfig.DEBUG, which Gradle sets to false in release builds, and R8 then removes the debug branches. Delete any other debug switches, such as hidden menus and test accounts, from release code."
  },
  "code.no-tapjacking-protection": "Call setFilterTouchesWhenObscured(true), or set android:filterTouchesWhenObscured=\"true\", on buttons that confirm payments, permissions or sign-in. On Android 12 and later also call Window.setHideOverlayWindows(true) in the sensitive activity, which needs the HIDE_OVERLAY_WINDOWS permission.",
  "code.oauth-pkce": {
    "*": "Run the login in a Custom Tab through AppAuth-Android. It sends a PKCE challenge by default and keeps the password out of your app.",
    "Authorization code flow without PKCE": "Add PKCE. Generate a random code_verifier of 43 to 128 characters, send its SHA-256 digest as code_challenge with code_challenge_method=S256 in the authorization request, and send the verifier in the token request. AppAuth-Android does this by default, and an https App Link as the redirect URI blocks other apps from claiming the code.",
    "OAuth login page loaded in a WebView": "Open the login page in a Custom Tab with androidx.browser CustomTabsIntent, or use AppAuth-Android. The app then never sees the password, and the user's browser session and password manager work. Google blocks OAuth requests from embedded WebViews."
  },
  "code.no-anti-debug": "Check Debug.isDebuggerConnected() and ApplicationInfo.FLAG_DEBUGGABLE at startup, and request a Play Integrity API verdict that your server verifies before it serves sensitive data. Hooking tools can patch local checks, so apply them to the high-risk flows and expect determined attackers to get past them.",
  "privacy.trackers": "Remove SDKs the app does not need. For those you keep, switch off automatic collection until the user consents, for example FirebaseAnalytics.setAnalyticsCollectionEnabled(false) or the firebase_analytics_collection_enabled meta-data flag. List the data they collect in the Play Console data safety form and your privacy policy.",
  "secrets.hardcoded-values": "Remove the literal from code and resources, rotate the value, and load secrets from your backend after sign-in. For API keys that must ship, restrict them to your package name and signing certificate in the provider's console. Anything in the APK can be extracted, including values from local.properties or a Gradle secrets plugin.",
  "secrets.binary-strings": "Remove the secret from the compiled code, rotate it, and fetch it from your backend after sign-in. For API keys that must ship, restrict them to your package name and signing certificate in the provider's console. Packing or obfuscating the app only delays extraction.",
  "dyn.logcat-secrets": "Delete the log calls that print passwords, tokens or personal data. Wrap debug logging in if (BuildConfig.DEBUG), and add an R8 -assumenosideeffects rule for android.util.Log so release builds drop the calls. Rotate any token that appeared in the log.",
  "dyn.crash": "Read the stack trace with adb logcat -b crash and fix the unhandled exception. A launch without the expected extras usually crashes on a null Intent extra or uninitialized state. Validate every extra and Uri in onCreate, and call finish() when they are invalid.",
  "dyn.cleartext-connection": "Move the connection to TLS and set cleartextTrafficPermitted=\"false\" in the network security config, with android:usesCleartextTraffic=\"false\" in the manifest. Check third-party SDKs for the endpoints they open, and replace or configure any that use plain sockets or http.",
  "dyn.storage-secrets": "Encrypt the value with an AES/GCM/NoPadding key held in the Android Keystore before writing it, or keep it in memory only. Keep tokens short-lived, exclude the files from backups with android:dataExtractionRules, and clear the stored data at sign-out.",
  "dyn.world-readable": "Create files with Context.openFileOutput(name, MODE_PRIVATE), and remove File.setReadable(true, false) calls or chmod commands in native code that grant access to other users. Share a file with another app through a FileProvider content:// URI with a temporary grant.",
  "dyn.external-storage": "Write private data to Context.getFilesDir() or Context.getExternalFilesDir() in place of shared storage. Use MediaStore or the Storage Access Framework for files the user should keep, and encrypt sensitive content before writing it to a shared location.",
  "dyn.exported-reachable": "Set android:exported=\"false\" on activities that should not start from outside the app. If other apps must open it, check in onCreate that the user is signed in and send them to the login screen otherwise, or guard the activity with a signature-level android:permission.",
  "dyn.provider-query": "Set android:exported=\"false\" on the provider, or protect it with android:readPermission at the signature level. Check the caller with Binder.getCallingUid() or checkCallingPermission() in query(), and return only the rows and columns that caller may see.",
  "dyn.listening-port": "Bind the server to the loopback address 127.0.0.1 and require an authentication token on each request, since any app on the phone can connect to a loopback port. Stop the listener when the feature is idle, and remove debug servers from release builds.",
  "dyn.webview-devtools": "Call WebView.setWebContentsDebuggingEnabled(true) only inside if (BuildConfig.DEBUG). With the call removed from release builds, the webview_devtools_remote socket is not opened and Chrome DevTools cannot attach to the app's pages.",
  "dyn.notification-secrets": "Keep the secret out of the notification text. Set setVisibility(NotificationCompat.VISIBILITY_PRIVATE) with a setPublicVersion() notification that omits the value, and show one-time codes inside the app.",
  "dyn.plaintext-database": "Encrypt the database with SQLCipher (net.zetetic:sqlcipher-android) using a random passphrase wrapped by an Android Keystore key, or encrypt sensitive columns with AES/GCM/NoPadding before you insert them. Delete the old unencrypted file after you migrate, and exclude databases from backups.",
  "dyn.provider-injection": "Bind values with selection arguments (?) in query, update and delete, and check the projection against a fixed column list, or use SQLiteQueryBuilder.setStrict(true) with setProjectionMap. In openFile, resolve the path with getCanonicalPath() and reject any path outside the allowed directory. Set android:exported=\"false\" when other apps do not need the provider.",
  "code.clipboard-read": "Read the clipboard only in response to an explicit user action such as a paste button, and use ClipboardManager.getPrimaryClipDescription() to check the type before reading the content. Remove clipboard listeners unless the feature truly needs them, and never forward clipboard content to a server.",
  "code.deprecated-security-api": {
    "*": "Plan a migration off androidx.security:security-crypto. Store the data in Jetpack DataStore and encrypt values with an AEAD primitive from Tink (for example AesGcmKeyManager) whose keyset is wrapped by an Android Keystore key through AndroidKeysetManager. Test the migration on devices where the old master key is already broken, so users do not lose data.",
    "SafetyNet Attestation": "Move to the Play Integrity API and check its verdict on your server. Treat the verdict as a risk signal, since client checks can be bypassed."
  },
  "code.passkey-weak-config": {
    "*": "Set userVerification to required in every passkey create and get request, and have the server reject assertions whose authenticator data lacks the user-verified flag. Generate a fresh random challenge of at least 16 bytes on the server for each request, bind it to the session and accept it once.",
    "Passkey does not require user verification": "Set userVerification to required in every passkey create and get request. Have the server reject any assertion whose authenticator data lacks the user-verified (UV) flag, because the client setting alone cannot be trusted.",
    "Hardcoded passkey challenge": "Generate a new random challenge of at least 16 bytes on the server for each ceremony, bind it to the session and accept it only once. Remove the fixed value from the app, and verify the challenge in clientDataJSON when the response arrives."
  },
  "code.temp-file-write": "Keep sensitive data in memory, or write it to Context.getFilesDir() with an EncryptedFile-style AEAD envelope from Tink. When a temporary file is unavoidable, create it in getCodeCacheDir or getNoBackupFilesDir, delete it in a finally block as soon as it is used, and exclude the cache from backups.",
  "code.timing-unsafe-compare": "Compare secrets with MessageDigest.isEqual on their byte arrays, which takes the same time for every input of equal length. Better, never compare raw passwords in the app: verify them on the server against a salted hash from a slow function such as bcrypt or Argon2.",
  "code.stack-trace-leak": {
    "*": "Remove printStackTrace calls and log failures through a logger that is silent in release builds, for example Timber with a debug-only tree. Show the user a short, generic error message and send the detail to a crash reporter instead.",
    "Stack trace shown to the user": "Show the user a short, generic error such as 'Something went wrong' and send the exception to a crash reporter. Keep stack traces, class names and server messages out of any text the screen can display."
  },
  "code.malware-indicators": {
    "*": "Confirm where the address or call comes from. Remove hidden-service links, free-domain URLs and device-admin calls that no feature uses, and make required endpoints a fixed, documented HTTPS host on a domain you own.",
    "Tor onion address": "Remove the .onion address unless the app is a Tor client by design. If it is, document it, route it through a maintained library such as Tor Android or Orbot, and keep it out of configuration an attacker can edit.",
    "Link on a free-registration domain": "Move the endpoint to a domain you register and control, served over HTTPS with certificate pinning. Remove leftover test URLs, because abandoned free domains can be claimed by anyone.",
    "Device wipe or lock call": "Call DevicePolicyManager lockNow, wipeData and resetPassword only in an app that is a registered device administrator for a real management purpose. Remove the calls from other apps, and drop the device-admin receiver declaration from the manifest if it is not needed."
  },
  "code.compose-saved-secret": "Keep passwords and tokens in a regular remember block, or in a ViewModel field that is not saved, so they never reach the saved-instance bundle. Clear the value when the screen leaves composition and set android:allowBackup to false or exclude the saved state from backups.",
  "manifest.sensitive-services": {
    "*": "Declare this capability only if a feature of the app needs it, and remove the component and its permission when it does not. Tell the user why it is needed before the system settings screen opens, and keep the code that handles the data narrow and audited.",
    "Accessibility service": "Remove the accessibility service unless the app is an assistive tool. If it is one, restrict it with android:accessibilityEventTypes and canRetrieveWindowContent only as far as the feature requires, set android:isAccessibilityTool honestly, and never forward screen content off the phone.",
    "Notification listener": "Remove the notification listener service unless reading notifications is the product. If it is, filter by package in onNotificationPosted, keep the content in memory, and keep codes and message text off the network and out of logs.",
    "Device administrator": "Drop the device admin receiver, and use the Device Policy Controller or a work profile through Android Enterprise if you need management. Declare only the policies in the metadata XML that the product needs, because wipe and lock powers make the app a high-value target.",
    "Starts at boot": "Remove the BOOT_COMPLETED receiver unless a feature must run right after boot, and schedule periodic work with WorkManager instead. Keep the receiver's work short and avoid starting visible UI or network calls from it.",
    "SMS receiver with raised priority": "Remove the android:priority attribute from the SMS filter, and read one-time codes through the SMS Retriever API or SMS User Consent API so no SMS permission is needed. Keep the receiver non-exported if it is only for system broadcasts.",
    "Cross-profile access": "Remove android:crossProfile and INTERACT_ACROSS_PROFILES unless the product needs work and personal instances to talk. If it does, whitelist the connected app with CrossProfileApps APIs, validate every message from the other profile, and keep corporate data on the work side."
  },
  "manifest.android14-requirements": {
    "*": "Raise the manifest to the Android 14 rules: give foreground services a foregroundServiceType and the matching FOREGROUND_SERVICE_* permission, and give every intent filter an action. Test the app on an Android 14 device, since the failure appears at runtime.",
    "Service without foregroundServiceType": "Add android:foregroundServiceType to the service, for example dataSync or mediaPlayback, and declare the matching android.permission.FOREGROUND_SERVICE_* permission. Pass the same type to startForeground, and remove FOREGROUND_SERVICE if the app never runs a foreground service.",
    "Intent filter without an action": "Add the action the component answers to inside the intent filter, or delete the filter if the component is only started by explicit Intent. An action-less filter matches nothing on Android 14 and later, so keep the filter only when it has an action."
  },
  "package.protector": "Treat protected builds as a bounded view: run a dynamic session and test on a device, because the real code is hidden from static scanning. If you are the developer, keep the protector's configuration current, and do not rely on it as the only defense since packers can be unpacked.",
  "package.hybrid-web": {
    "*": "Harden the web layer of the hybrid app: add a strict Content-Security-Policy meta tag, avoid eval and new Function, and keep navigation limited to your own origins. Load only local content and HTTPS, and turn off web debugging in release builds.",
    "No Content Security Policy in index.html": "Add a meta tag such as <meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; script-src 'self'; connect-src https://api.example.com\"> to index.html. Tighten each directive to the origins the app really uses, and test that nothing breaks without 'unsafe-inline'.",
    "Capacitor allows cleartext": "Remove server.cleartext from capacitor.config.json, or set it to false, and serve every resource over HTTPS. Test against a staging server with a valid certificate instead of relaxing TLS.",
    "Capacitor allows navigation anywhere": "Replace the wildcard in server.allowNavigation with the exact hosts the app needs. Leave external links to the system browser through the Browser plugin, so third-party pages never get the native bridge.",
    "Capacitor web debugging enabled": "Set webContentsDebuggingEnabled to false in capacitor.config.json for release builds, or keep it in a debug-only config file. Check the shipped APK for the value afterwards."
  },
  "package.react-native": {
    "*": "Keep secrets and debug settings out of the JavaScript bundle. Store tokens in the Android Keystore through react-native-keychain, build release bundles with --dev false, and strip console calls with babel-plugin-transform-remove-console.",
    "Secret saved in AsyncStorage": "Move tokens and passwords to react-native-keychain or expo-secure-store, which keep them in the Android Keystore. Keep only non-sensitive preferences in AsyncStorage, and clear stored values on logout.",
    "Development mode left on": "Build the release bundle with --dev false (or the Gradle release variant, which does this by default) and check that __DEV__ is false in the shipped bundle. Fail the release pipeline if the bundle contains development flags.",
    "Secret written with console.log": "Remove console.log calls that print tokens, passwords or authorization headers, and strip console output in production with babel-plugin-transform-remove-console. Use a logging helper that redacts sensitive fields.",
    "Metro dev server address in the bundle": "Build the release bundle with --dev false and bundle it into the APK, so it never asks a Metro server for code. Remove hardcoded development hosts from configuration and use environment files per build type.",
    "Hermes bytecode: JavaScript not readable": "Do not treat Hermes as protection for secrets: keep keys and sensitive logic on the server. For testing, disassemble the bundle with hbc-disassembler or use a dynamic session to see what the app does."
  },
  "package.flutter": "Store tokens and passwords with flutter_secure_storage, which uses the Android Keystore, and keep only harmless settings in shared_preferences. Build release apps with --obfuscate and --split-debug-info, and move truly sensitive values off the device.",
  "package.unity": "Do not store tokens, purchases or scores that must be trusted in PlayerPrefs. Encrypt sensitive values with a key from the Android Keystore through a native plugin, or validate them on a server. Obfuscate the build with IL2CPP and an assembly obfuscator.",
  "package.dotnet": {
    "*": "Keep certificate validation on and store secrets with SecureStorage. Remove test-time shortcuts before release, and compile with the AOT and linker settings that shrink and obfuscate assemblies.",
    "Custom certificate validation": "Delete the ServerCertificateValidationCallback that always returns true, and let the platform validate certificates. If you need pinning, compare the certificate's public key hash inside the callback and return false for any other value.",
    "Preferences without SecureStorage": "Save tokens and passwords with SecureStorage.SetAsync, which uses the Android Keystore, and keep only harmless settings in Preferences. Clear the secure values on logout."
  },
  "code.no-obfuscation": "Enable R8 in the release build with minifyEnabled true and shrinkResources true, and keep the ProGuard rules file narrow. Check the release mapping file is archived privately, and consider DexGuard or an equivalent if the app holds sensitive logic.",
  "native.strings": {
    "*": "Remove cleartext URLs and weak algorithms from native code, move requests to HTTPS and use modern primitives such as AES-GCM and SHA-256. Rebuild the library without unused crypto code.",
    "Cleartext URL": "Change the http:// address in the native code to https:// and make sure the code verifies certificates. Network requests made in native code skip the network security config, so check them explicitly.",
    "Weak crypto name": "Replace MD5, SHA-1, DES, RC4 and ECB use with AES-GCM and SHA-256 or SHA-3 from a maintained library such as libsodium or BoringSSL. If the name comes from an unused library module, build without it."
  },
  "privacy.sdk-inventory": {
    "*": "Keep an inventory of third-party SDKs and their versions, and update them on a schedule using Gradle dependency checks or Dependabot. Remove SDKs the product no longer uses, and review each one's permissions and data collection against your privacy policy and the Play data safety form.",
    "Facebook client token in resources": "Treat the Facebook client token as public, and check in the Facebook app dashboard that it grants nothing beyond what an anonymous client may do. Rotate it if it was ever combined with an app secret, and keep the app secret on the server only."
  },
  "dyn.exported-service": "Set android:exported=\"false\" on services that only your app starts. If other apps must bind or start it, protect it with a signature-level android:permission and validate the caller with Binder.getCallingUid() in onStartCommand or onBind. Treat every extra in the Intent as untrusted input.",
  "dyn.exported-receiver": "Set android:exported=\"false\" on receivers that only your app targets, and send in-app broadcasts with LocalBroadcastManager-style alternatives such as SharedFlow or setPackage(). If outside apps must send to it, require a signature permission, and check the action and every extra before acting.",
  "dyn.provider-write": "Set android:exported=\"false\" on the provider, or protect writes with android:writePermission at the signature level. Check the caller in insert, update and delete with Binder.getCallingUid(), and validate every column and value against a fixed list before touching the database.",
  "dyn.key-files": "Do not ship or write key material into the app's folders. Generate keys in the Android Keystore with KeyGenParameterSpec so they cannot be exported, and fetch client certificates after sign-in. If a file is unavoidable, encrypt it with a Keystore-wrapped key, and exclude it from backups.",
  "dyn.log-stack-trace": "Remove printStackTrace and Log.e calls that print whole exceptions in release builds. Log through a wrapper that is silent unless BuildConfig.DEBUG is true, and send failures to a crash reporter that keeps them off the device log.",
  "dyn.app-links": "Publish a Digital Asset Links file at https://<host>/.well-known/assetlinks.json that lists your package name and the SHA-256 fingerprint of your release signing certificate. Keep android:autoVerify=\"true\" on the intent filter, then check the state with adb shell pm get-app-links and fix any host that is not verified.",
  "dyn.flag-secure": "Call window.setFlags(WindowManager.LayoutParams.FLAG_SECURE, WindowManager.LayoutParams.FLAG_SECURE) in the activities that show sensitive data, ideally in a base activity. On Android 13 and later also call setRecentsScreenshotEnabled(false), so the recent-apps thumbnail stays blank.",
  "dyn.root-reaction": "Check the device at startup and before sensitive actions: use Google's Play Integrity API for a server-verified verdict, optionally with a local library such as RootBeer, and let the server decide what a rooted device may do. Client checks can be bypassed, so treat the result as a risk signal.",
  "dyn.package-flags": {
    "*": "Fix the setting in the manifest and rebuild: set android:debuggable to false, remove android:testOnly, and set android:allowBackup to false or add dataExtractionRules. Install the release variant when you test, and check dumpsys package afterwards.",
    "Installed build is debuggable": "Set android:debuggable to false in release builds and install the release variant, not a debug build, on test phones. Check the merged manifest, since a library can add the attribute back.",
    "Installed build is test-only": "Remove android:testOnly from the manifest, and build the release variant without the -t install flag. A test-only flag in a build users receive is a build pipeline fault, so check the release script as well.",
    "Backups are on for the installed build": "Set android:allowBackup to false if the app holds nothing worth restoring. Otherwise exclude databases, shared preferences and tokens with android:dataExtractionRules and android:fullBackupContent, and require device-to-device transfer encryption."
  },
  "dyn.work-profile": "Review every cross-profile path of the app. Keep corporate data in the work profile, validate each Intent that crosses profiles, and use the Android Enterprise managed configuration to restrict sharing. Test backups, clipboard and file sharing between the two profiles.",
  "signature.algorithm": "Sign releases with an RSA key of at least 3072 bits or an EC P-256 key, and build with apksigner or Android Gradle Plugin so the v2 and v3 schemes use SHA-256 or stronger. Generate the new key in a new keystore and migrate through APK Signature Scheme v3 key rotation, since changing the key breaks updates for existing users otherwise.",
  "code.no-root-detection": "Add a root check at startup and before sensitive actions: use Google's Play Integrity API for a server-verified device verdict, optionally with a library such as RootBeer for local signals. Treat the result as a risk signal and decide server-side what to allow, since client checks can be bypassed.",
  "code.partial-obfuscation": "Narrow the -keep rules in proguard-rules.pro so login, crypto, payment and license classes are renamed with the rest. Keep names only for classes that reflection or serialization needs, and check the release mapping file to see which classes survived with their names.",
  "code.key-reuse": "Derive one key per purpose from a master key with HKDF, using a different info string for encryption and for the MAC. Better, use an AEAD mode such as AES/GCM/NoPadding, which gives confidentiality and integrity with a single key.",
  "code.copy-paste-allowed": "Disable selection and long-click on fields that show sensitive values with android:longClickable=\"false\" and android:textIsSelectable=\"false\", or set a custom ActionMode callback that returns false. Use android:inputType textPassword for secrets the user types, and clear the clipboard after a short delay for values you must let them copy.",
  "dyn.granted-permissions": "Request only the permissions a feature needs, at the moment the user starts that feature, and use the narrower alternative where one exists: the photo picker in place of READ_MEDIA_*, approximate location in place of fine, and the SMS Retriever in place of READ_SMS. Remove permissions from the manifest that no code uses, and release unused ones with revokeSelfPermissionsOnKill.",
  "code.sql-from-variable": "Pass SQL text only as a fixed string, and bind every value with selection arguments or ? placeholders in execSQL, rawQuery and compileStatement. If a column or table name must vary, choose it from a fixed allow-list in code. Prefer Room, which generates parameterized queries.",
  "code.download-mobile-only": "Remove setAllowedNetworkTypes(NETWORK_MOBILE) and let the system pick the network, or allow Wi-Fi as well with NETWORK_WIFI | NETWORK_MOBILE. Offer large downloads over Wi-Fi only, and verify the file with a checksum or signature after the download.",
  "network.single-pin": "Add a second pin to the pin-set, for a backup key kept offline or the next certificate, so a rotation does not lock users out. Set an expiration that leaves time to ship an update.",
  "package.vulnerable-libraries": "Update the library to the fixed version named in the finding, or remove it if nothing uses it. Add a dependency check such as OWASP Dependency-Check to the build so outdated versions are caught early.",
  "package.unity-intent": "Rebuild the game with a Unity version that has the October 2025 fix, or apply Unity's binary patch to the shipped runtime, then publish the update. Unexporting the activity is not an option, because it is the launcher.",
  "code.logout-keeps-session": "On logout, clear the stored tokens and user data (SharedPreferences, databases, encrypted stores), delete cookies and cached WebView data, and revoke the session on the server.",
  "code.jwt-misuse": "Verify every JWT on the server with a pinned algorithm and a key that never leaves the server. Reject alg none, and never put a signing secret in the app.",
  "network.endpoint-inventory": "Use the list to scope server-side testing: confirm that each host needs to be public, uses TLS and enforces authorization.",
  "dyn.logcat-http-url": "Use https for every request and set cleartextTrafficPermitted to false in the network security config, so a plain request fails instead of leaving the phone."
};

/** The recommendation for a finding, or null when the rule has none. */
export function recommendationFor(ruleId, title) {
  const r = REC[ruleId];
  if (!r) return null;
  if (typeof r === 'string') return r;
  return r[String(title || '').split(':')[0]] ?? r['*'] ?? null;
}
